function applyEvents(initial, events) {
  if (!Number.isInteger(initial)) {
    throw new Error('initial must be an integer');
  }

  let balance = initial;
  const applied = [];
  const queued = [];
  const appliedIds = new Set();
  const queuedIds = new Set();

  for (const e of events) {
    if (!Number.isInteger(e.amountMinor)) {
      throw new Error('amountMinor must be an integer');
    }

    if (e.synced) {
      if (appliedIds.has(e.id)) {
        continue;
      }
      if (queuedIds.has(e.id)) {
        const idx = queued.indexOf(e.id);
        if (idx !== -1) {
          queued.splice(idx, 1);
        }
        queuedIds.delete(e.id);
        balance += e.amountMinor;
        applied.push(e.id);
        appliedIds.add(e.id);
      } else {
        balance += e.amountMinor;
        applied.push(e.id);
        appliedIds.add(e.id);
      }
    } else {
      if (queuedIds.has(e.id) || appliedIds.has(e.id)) {
        continue;
      }
      queued.push(e.id);
      queuedIds.add(e.id);
    }
  }

  return { balanceMinor: balance, applied, queued };
}

function applyEvents(initial, events) {
  if (!Number.isInteger(initial)) {
    throw new Error('Invalid initial balance');
  }
  let balanceMinor = initial;
  const applied = [];
  const queued = [];
  const appliedSet = new Set();
  const queuedSet = new Set();
  for (let i = 0; i < events.length; i++) {
    const event = events[i];
    const amountMinor = event.amountMinor;
    if (!Number.isInteger(amountMinor)) {
      throw new Error('Invalid amountMinor');
    }
    const id = event.id;
    if (event.synced) {
      if (!appliedSet.has(id)) {
        if (queuedSet.has(id)) {
          queuedSet.delete(id);
        }
        appliedSet.add(id);
        applied.push(id);
        balanceMinor += amountMinor;
      }
    } else {
      if (!appliedSet.has(id) && !queuedSet.has(id)) {
        queuedSet.add(id);
        queued.push(id);
      }
    }
  }
  return {
    balanceMinor: balanceMinor,
    applied: applied,
    queued: queued.filter(function (id) { return queuedSet.has(id); })
  };
}

function applyEvents(initial, events) {
  if (!Number.isInteger(initial)) {
    throw new Error('initial must be an integer');
  }
  if (!Array.isArray(events)) {
    throw new Error('events must be an array');
  }
  let balanceMinor = initial;
  const applied = [];
  const appliedSeen = new Set();
  const queuedOrder = [];
  const queuedSeen = new Set();
  for (const event of events) {
    if (event === null || typeof event !== 'object') {
      throw new Error('each event must be an object');
    }
    if (!Number.isInteger(event.amountMinor)) {
      throw new Error('amountMinor must be an integer');
    }
    const id = event.id;
    if (appliedSeen.has(id)) {
      continue;
    }
    if (event.synced) {
      queuedSeen.delete(id);
      appliedSeen.add(id);
      applied.push(id);
      balanceMinor += event.amountMinor;
    } else if (!queuedSeen.has(id)) {
      queuedSeen.add(id);
      queuedOrder.push(id);
    }
  }
  return {
    balanceMinor: balanceMinor,
    applied: applied,
    queued: queuedOrder.filter((id) => queuedSeen.has(id))
  };
}
